<template><div class="app-container"><el-card><template #header>变更管理(ECN)</template><el-table v-loading="loading" :data="list"><el-table-column label="变更单号" prop="changeNumber" width="140" /><el-table-column label="标题" prop="title" /><el-table-column label="状态" prop="status" width="100"><template #default="scope"><el-tag :type="statusType(scope.row.status)">{{scope.row.status}}</el-tag></template></el-table-column><el-table-column label="影响级别" prop="impactLevel" width="100" /><el-table-column label="创建时间" prop="createTime" width="160" /><el-table-column label="操作" width="200" fixed="right"><template #default="scope"><el-button link type="primary" @click="handleAnalyze(scope.row)">分析影响</el-button><el-button link type="success" @click="handlePropagate(scope.row)" v-if="scope.row.status==='ANALYZED'">传播变更</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="queryParams.pageNum" v-model:limit="queryParams.pageSize" @pagination="getList" /></el-card></div></template>
<script setup lang="ts">import { ref, reactive, onMounted } from 'vue';import { listEcnOrders, analyzeImpact, propagateChange } from '@/api/cpq/ecn';import { ElMessage } from 'element-plus';const loading=ref(false), total=ref(0), list=ref<any[]>([]);const queryParams=reactive({pageNum:1,pageSize:10});const statusType=(s:string)=>s==='DRAFT'?'info':s==='ANALYZING'?'warning':s==='ANALYZED'?'primary':s==='IMPLEMENTED'?'success':'danger';const getList=async()=>{loading.value=true;try{const res=await listEcnOrders(queryParams);list.value=res.rows;total.value=res.total}finally{loading.value=false}};const handleAnalyze=async(row:any)=>{await analyzeImpact(row.changeOrderId);ElMessage.success('影响分析完成');getList()};const handlePropagate=async(row:any)=>{await propagateChange(row.changeOrderId);ElMessage.success('变更传播完成');getList()};onMounted(getList)</script>
